package com.adent.orders.domain; import com.adent.shared.domain.BaseEntity; import jakarta.persistence.*; import java.time.*; import java.util.UUID; @Entity @Table(name="radiology_orders") public class RadiologyOrder extends BaseEntity { @Column(name="tenant_id",nullable=false) private UUID tenantId;@Column(name="patient_id",nullable=false) private UUID patientId;@Column(name="encounter_id") private UUID encounterId;@Column(name="requested_by_staff_id") private UUID requestedByStaffId;@Column(name="study_type",nullable=false,length=120) private String studyType;@Column(name="tooth_codes",length=250) private String toothCodes;@Column(columnDefinition="text") private String instructions;@Column(nullable=false,length=30) private String status="REQUESTED";@Column(name="result_url",length=500) private String resultUrl;@Column(name="result_notes",columnDefinition="text") private String resultNotes;@Column(name="delivered_at") private OffsetDateTime deliveredAt; public UUID getTenantId(){return tenantId;}public void setTenantId(UUID v){tenantId=v;}public UUID getPatientId(){return patientId;}public void setPatientId(UUID v){patientId=v;}public UUID getEncounterId(){return encounterId;}public void setEncounterId(UUID v){encounterId=v;}public UUID getRequestedByStaffId(){return requestedByStaffId;}public void setRequestedByStaffId(UUID v){requestedByStaffId=v;}public String getStudyType(){return studyType;}public void setStudyType(String v){studyType=v;}public String getToothCodes(){return toothCodes;}public void setToothCodes(String v){toothCodes=v;}public String getInstructions(){return instructions;}public void setInstructions(String v){instructions=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getResultUrl(){return resultUrl;}public void setResultUrl(String v){resultUrl=v;}public String getResultNotes(){return resultNotes;}public void setResultNotes(String v){resultNotes=v;}public OffsetDateTime getDeliveredAt(){return deliveredAt;}public void setDeliveredAt(OffsetDateTime v){deliveredAt=v;} }
